    "blog.post4.title": "\u4e3a\u4ec0\u4e48\u6211\u4eec\u9009\u62e9CRDT\u800c\u4e0d\u662fRaft\u6765\u5b9e\u73b0\u591a\u6570\u636e\u4e2d\u5fc3\u590d\u5236",
